styles:
.b-press-articles {
    container-type: inline-size;
}

.b-press-articles__title {
    margin: 0 0 1em;
}

.b-press-articles__list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 18em), 1fr));
    gap: 1.5em;
    margin: 0;
    padding: 0;
    list-style: none;
}

/* A grid or flex box outranks the browser's own [hidden] rule. */
.b-press-articles__list[hidden],
.b-press-articles__card[hidden],
.b-press-articles__outlet[hidden] {
    display: none;
}

.b-press-articles__item {
    min-width: 0;
}

.b-press-articles__card {
    display: flex;
    flex-direction: column;
    gap: 0.5em;
    box-sizing: border-box;
    height: 100%;
    padding: 1.25em;
    border: 1px solid color-mix(in srgb, currentColor 15%, transparent);
    border-radius: 0.75em;
}

.b-press-articles__outlet {
    display: flex;
    align-items: center;
    gap: 0.5em;
    margin: 0;
    font-size: 0.9em;
}

.b-press-articles__outlet a {
    color: inherit;
}

.b-press-articles__logo {
    display: block;
    width: auto;
    min-width: 0;
    height: 1.5em;
    object-fit: contain;
}

.b-press-articles__name {
    margin: 0;
    font-size: 1.1em;
}

.b-press-articles__name a {
    color: inherit;
}

.b-press-articles__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0 0.75em;
    margin: 0;
    font-size: 0.9em;
    opacity: 0.7;
}

.b-press-articles__excerpt {
    flex: 1;
    margin: 0;
}

.b-press-articles__pdf {
    margin: 0;
}
